--
-- Table structure for table `order_entity`
--

DROP TABLE IF EXISTS `order_entity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_entity` (
  `id` int NOT NULL AUTO_INCREMENT,
  `no` varchar(255) NOT NULL DEFAULT '',
  `desc` varchar(255) NOT NULL,
  `totalPrice` float NOT NULL,
  `discount` int NOT NULL,
  `companyId` int DEFAULT NULL,
  `userId` int DEFAULT NULL,
  `templateId` int DEFAULT NULL,
  `status` enum('0','1','2') NOT NULL DEFAULT '0',
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `delete_time` datetime(6) DEFAULT NULL,
  `customerId` int DEFAULT NULL,
  `realTotalPrice` float NOT NULL DEFAULT '0',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `deletedAt` datetime(6) DEFAULT NULL,
  `payment` enum('0','1','2','3') NOT NULL DEFAULT '1',
  `chargeId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_5646dec7dc337e5302c7f9d6ad` (`no`),
  KEY `FK_4480b7afbd07c9d3dfa5324862a` (`customerId`),
  KEY `FK_c5a748879aa004a90c8032cbf38` (`companyId`),
  KEY `FK_c8ab590f1e10afcf1637e71a71e` (`userId`),
  KEY `FK_b49010043515283aa3e1d60c4a7` (`chargeId`),
  CONSTRAINT `FK_4480b7afbd07c9d3dfa5324862a` FOREIGN KEY (`customerId`) REFERENCES `customer` (`id`),
  CONSTRAINT `FK_b49010043515283aa3e1d60c4a7` FOREIGN KEY (`chargeId`) REFERENCES `charges` (`id`),
  CONSTRAINT `FK_c5a748879aa004a90c8032cbf38` FOREIGN KEY (`companyId`) REFERENCES `company` (`id`),
  CONSTRAINT `FK_c8ab590f1e10afcf1637e71a71e` FOREIGN KEY (`userId`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

